package com.example.starter.pointcloud.model;

/**
 * 块级压缩方式。
 */
public enum Compression {

    /** 不压缩。 */
    NONE,

    /** GZIP 压缩；若压缩失败或压缩结果不小于原始数据则回退为 {@link #NONE}。 */
    GZIP
}

package com.example.starter.pointcloud.model;

/**
 * 三维点（不含时间），用于查询几何体定义。
 *
 * @param x X 坐标，单位米
 * @param y Y 坐标，单位米
 * @param z Z 坐标，单位米
 */
public record Vec3(double x, double y, double z) {
}

package com.example.starter.pointcloud.model;

/**
 * 单个 LiDAR 点。
 *
 * @param x              X 坐标，单位米
 * @param y              Y 坐标，单位米
 * @param z              Z 坐标，单位米
 * @param timestampNanos 采集时间戳，纳秒，单调时钟语义；闭区间比较
 */
public record Point(double x, double y, double z, long timestampNanos) {
}

package com.example.starter.pointcloud.model;

/**
 * 三维轴对齐包围盒，边界均为闭区间。
 *
 * @param minX 最小 X，单位米（含）
 * @param minY 最小 Y，单位米（含）
 * @param minZ 最小 Z，单位米（含）
 * @param maxX 最大 X，单位米（含）
 * @param maxY 最大 Y，单位米（含）
 * @param maxZ 最大 Z，单位米（含）
 */
public record BoundingBox(double minX, double minY, double minZ,
                          double maxX, double maxY, double maxZ) {

    /**
     * 判断两个包围盒是否相交（闭区间，面接触视为相交）。
     */
    public boolean intersects(BoundingBox other) {
        return !(this.maxX < other.minX || this.minX > other.maxX
                || this.maxY < other.minY || this.minY > other.maxY
                || this.maxZ < other.minZ || this.minZ > other.maxZ);
    }
}

