package com.example.starter.pointcloud.api;

import com.example.starter.pointcloud.model.Compression;
import com.example.starter.pointcloud.model.Point;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

import java.util.List;

/**
 * 写入块请求。
 *
 * @param chunkId     块唯一标识，非空
 * @param version     块版本，非负
 * @param source      数据来源，非空
 * @param compression 请求的压缩方式；实际落盘可能因回退为 NONE
 * @param points      点列表，非空；点在列表中的顺序即块内点序
 */
public record WriteChunkRequest(
        @NotBlank String chunkId,
        @PositiveOrZero long version,
        @NotBlank String source,
        @NotNull Compression compression,
        @NotEmpty List<@NotNull Point> points) {
}

package com.example.starter.pointcloud.api;

import jakarta.validation.constraints.NotNull;

/**
 * 闭区间 Box 查询请求；边界上的点必须包含。
 */
public record BoxQueryRequest(
        @NotNull Double minX,
        @NotNull Double minY,
        @NotNull Double minZ,
        @NotNull Double maxX,
        @NotNull Double maxY,
        @NotNull Double maxZ) {
}

package com.example.starter.pointcloud.api;

import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * Radius（球体）查询请求；球面边界上的点必须包含。
 */
public record RadiusQueryRequest(
        @NotNull Double centerX,
        @NotNull Double centerY,
        @NotNull Double centerZ,
        @NotNull @PositiveOrZero Double radiusMeters) {
}

package com.example.starter.pointcloud.api;

import com.example.starter.pointcloud.model.Vec3;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

import java.util.List;

/**
 * 轨迹走廊查询请求：点到折线的三维距离不超过半宽即命中（含边界）。
 *
 * @param vertices  折线顶点，至少 2 个
 * @param halfWidthMeters 走廊半宽，单位米
 */
public record CorridorQueryRequest(
        @NotEmpty List<@NotNull @Valid Vec3Holder> vertices,
        @NotNull @PositiveOrZero Double halfWidthMeters) {

    /**
     * 折线顶点传输对象。
     */
    public record Vec3Holder(@NotNull Double x, @NotNull Double y, @NotNull Double z) {

        public Vec3 toVec3() {
            return new Vec3(x, y, z);
        }
    }
}

