        if (src.length > Integer.MAX_VALUE - 32) {
            throw new IllegalArgumentException("source 过长");
        }
        long size = 8L + 4L + src.length + 4L + points.size() * 32L;
        if (size > Integer.MAX_VALUE) {
            throw new IllegalArgumentException("块内容过大");
        }
        ByteBuffer buf = ByteBuffer.allocate((int) size);
        buf.putLong(version);
        buf.putInt(src.length);
        buf.put(src);
        buf.putInt(points.size());
        for (Point p : points) {
            buf.putDouble(p.x());
            buf.putDouble(p.y());
            buf.putDouble(p.z());
            buf.putLong(p.timestampNanos());
        }
        return buf.array();
    }

