        ByteBuffer buf = ByteBuffer.allocate((int) size);
        buf.putLong(version);
        buf.putInt(src.length);
        buf.put(src);
        buf.putInt(points.size());
        for (Point p : points) {
            buf.putDouble(p.x());
            buf.putDouble(p.y());
            buf.putDouble(p.z());
            buf.putLong(p.timestampNanos());
        }
        return buf.array();
