     * 解析规范化内容，结构非法一律视为损坏。
     */
    private static Decoded parseCanonical(byte[] canonical, String checksum) {
        ByteBuffer buf = ByteBuffer.wrap(canonical);
        if (canonical.length < 16) {
            throw new CorruptChunkException("规范化内容过短");
        }
        long version = buf.getLong();
        int srcLen = buf.getInt();
        if (srcLen < 0 || srcLen > buf.remaining() - 4) {
            throw new CorruptChunkException("source 长度越界");
        }
        byte[] src = new byte[srcLen];
        buf.get(src);
        int pointCount = buf.getInt();
        if (pointCount < 0 || buf.remaining() != pointCount * 32L) {
            throw new CorruptChunkException("点数与剩余字节不一致");
        }
        List<Point> points = new ArrayList<>(pointCount);
        for (int i = 0; i < pointCount; i++) {
            points.add(new Point(buf.getDouble(), buf.getDouble(), buf.getDouble(), buf.getLong()));
        }
        return new Decoded(version, new String(src, StandardCharsets.UTF_8), points, checksum);
    }

