     *
     * @param fileName       正式块文件名
     * @param newlyPublished true 表示本次新发布；false 表示同名文件已存在（重试）
     */
    public record StoredChunk(String fileName, boolean newlyPublished) {
    }

    public Path rootDir() {
        return rootDir;
    }

    public Path chunkDir() {
        return chunkDir;
    }

    /**
     * 将块字节写入临时文件、回读校验后原子发布。
